namespace OCA\FilzmannPermissionMatrix\PublicApi\V1 {
 interface PermissionProvider{public function descriptor():PermissionProviderDescriptor;public function collect():PermissionProviderResult;} final class PermissionProviderDescriptor{public function __construct(...$a){}} final class PermissionCondition{private function __construct(public string $operator){}public static function authenticated():self{return new self('authenticated');}public static function self():self{return new self('self');}public static function nextcloudAdmin():self{return new self('nextcloud-admin');}} final class PermissionRule{public function __construct(public string $type,public string $name,public string $detail,public string $permission,public string $label,public string $effect,public string $scope,public PermissionCondition $condition,public string $source,public string $confidence){}} final class PermissionProviderResult{public function __construct(public array $rules,public bool $complete=true,public array $warnings=[]){}} final class RegisterPermissionProvidersEvent{public array $providers=[];public function register(PermissionProvider $p):void{$this->providers[]=$p;}}
