namespace { use OCA\AdRoom\Permission\RoomPermissionProvider;use OCA\AdRoom\Permission\RoomPermissionProviderListener;use OCA\FilzmannPermissionMatrix\PublicApi\V1\RegisterPermissionProvidersEvent;$provider=new RoomPermissionProvider();$rules=$provider->collect()->rules;$map=[];foreach($rules as $r)$map[$r->permission]=$r->condition->operator;if($map!==['room.read'=>'authenticated','booking.manage-own'=>'self','booking.manage-all'=>'nextcloud-admin','room.manage'=>'nextcloud-admin'])throw new RuntimeException('Der Raumrechtevertrag ist unvollständig oder überbreit.');$event=new RegisterPermissionProvidersEvent();(new RoomPermissionProviderListener($provider))->handle($event);if(($event->providers[0]??null)!==$provider)throw new RuntimeException('Lazy-Registrierung fehlt.');echo "Room permission provider tests passed\n";}
